{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Telmisartan, the highest-transfer analogue (0.9896), has an absolute oral bioavailability of 43% in healthy volunteers, directly above the 20% threshold and strongly supportive of high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Bumetanide (transfer 0.9881) shows an absolute oral bioavailability of 81% in healthy subjects, providing independent high-F evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Bosentan (transfer 0.9875) has an absolute oral bioavailability of 46% in fasting healthy subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Silodosin (transfer 0.9874) has an absolute oral bioavailability of 32.2% in healthy adult men, still well above the 20% threshold and supportive.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Indomethacin (transfer 0.9866) has essentially complete absolute oral bioavailability (~89-100%), strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Imatinib (transfer 0.9859) has a mean absolute oral bioavailability of 98%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Amlodipine (transfer 0.9859) has an absolute oral bioavailability of 81% in men, with other reports of 52-88%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "SAHA (transfer 0.9859) has an absolute oral bioavailability of 43% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well above the 20% threshold (32-100%), with no affirmative low-bioavailability evidence. The query is therefore predicted to have high oral bioavailability at the F≥20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule.",
    "The query contains ester, guanidine, and benzimidazole motifs not exactly matched by any single analogue, so first-pass metabolism or solubility effects are not directly characterized.",
    "All evidence is transferable by assay score but structurally diverse; no low-F analogue was retrieved to provide a counterbalancing anchor."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

